                "description": "Создание основного модуля сканера сот HoneycombScanner",
                "content": "#!/usr/bin/env python3\n# -*- coding: utf-8 -*-"+
                "\n\"\"\"\nHoneycomb Registry Scanner\nАвтоматическое сканирование и регистрация сот в системе Мандалы Симбиоза\n\"\"\"\n\n"+
                "import json\nimport os\nfrom pathlib import Path\nfrom typing import Dict, List, Any, Optional\nimport datetime"+
                "\nfrom dataclasses import dataclass\nfrom enum import Enum\n\n\nclass HoneycombStatus(str, Enum):\n    \"\"\"Статусы сот\"\"\"\n    ACTIVE = \"active\"\n    INACTIVE = \"inactive\"\n    DRAFT = \"draft\"\n    ARCHIVED = \"archived\"\n\n\nclass HoneycombType(str, Enum):\n    \"\"\"Типы сот\"\"\"\n    CORE = \"core\"\n    ROADMAP = \"roadmap\"\n    MODULE = \"module\"\n    INTEGRATION = \"integration\"\n    TASK = \"task\"\n    ANALYTICS = \"analytics\"\n    VISUALIZATION = \"visualization\"\n    INSTRUCTION = \"instruction\"\n    REGISTRY = \"registry\"\n    UNKNOWN = \"unknown\"\n\n\n@dataclass\nclass HoneycombInfo:\n    \"\"\"Информация о соте\"\"\"\n    path: str\n    identity: Dict[str, Any]\n    meta: Dict[str, Any]\n    content: Dict[str, Any]\n    navigation: Optional[Dict[str, Any]] = None\n    size_kb: float = 0.0\n    last_modified: Optional[datetime.datetime] = None\n    \n    @property\n    def module_id(self) -> str:\n        \"\"\"Идентификатор модуля\"\"\"\n        return self.identity.get(\"module_id\", \"\")\n    \n    @property\n    def name(self) -> str:\n        \"\"\"Название соты\"\"\"\n        return self.identity.get(\"name\", \"\")\n    \n    @property\n    def type(self) -> HoneycombType:\n        \"\"\"Тип соты\"\"\"\n        type_str = self.identity.get(\"type\", \"unknown\")\n        try:\n            return HoneycombType(type_str)\n        except ValueError:\n            return HoneycombType.UNKNOWN\n    \n    @property\n    def status(self) -> HoneycombStatus:\n        \"\"\"Статус соты\"\"\"\n        status_str = self.identity.get(\"status\", \"inactive\")\n        try:\n            return HoneycombStatus(status_str)\n        except ValueError:\n            return HoneycombStatus.INACTIVE\n    \n    @property\n    def layer(self) -> int:\n        \"\"\"Слой соты\"\"\"\n        return self.identity.get(\"layer\", 0)\n    \n    @property\n    def resonance(self) -> str:\n        \"\"\"Резонанс соты\"\"\"\n        return self.identity.get(\"resonance\", \"0%\")\n    \n    @property\n    def version(self) -> str:\n        \"\"\"Версия соты\"\"\"\n        return self.identity.get(\"version\", \"v1.0.0\")\n\n\nclass HoneycombScanner:\n    \"\"\"Сканер сот для системы Мандалы Симбиоза\"\"\"\n    \n    def __init__(self, base_path: str = \"honeycombs\"):\n        \"\"\"Инициализация сканера\"\"\"\n        self.base_path = Path(base_path)\n        self.scan_stats = {\n            \"total_files_scanned\": 0,\n            \"json_files_found\": 0,\n            \"honeycombs_found\": 0,\n            \"errors\": 0,\n            \"scan_start_time\": None,\n            \"scan_end_time\": None,\n            \"scan_duration\": None\n        }\n        self._honeycombs_cache: List[HoneycombInfo] = []\n    \n    def scan_directory(self, directory: Optional[str] = None) -> List[Dict[str, Any]]:\n        \"\"\"\n        Рекурсивное сканирование директории в поиске сот\n        \n        Args:\n            directory: Путь к директории для сканирования (None = base_path)\n            \n        Returns:\n            Список словарей с информацией о найденных сотах\n        \"\"\"\n        scan_path = Path(directory) if directory else self.base_path\n        \n        # Сброс статистики\n        self.scan_stats[\"scan_start_time\"] = datetime.datetime.now()\n        self.scan_stats[\"total_files_scanned\"] = 0\n        self.scan_stats[\"json_files_found\"] = 0\n        self.scan_stats[\"honeycombs_found\"] = 0\n        self.scan_stats[\"errors\"] = 0\n        self._honeycombs_cache = []\n        \n        honeycombs = []\n        \n        # Рекурсивный обход директории\n        for root, dirs, files in os.walk(scan_path):\n            root_path = Path(root)\n            \n            for file in files:\n                file_path = root_path / file\n                self.scan_stats[\"total_files_scanned\"] += 1\n                \n                # Проверяем только JSON файлы\n                if file.endswith(\".json\"):\n                    self.scan_stats[\"json_files_found\"] += 1\n                    \n                    try:\n                        # Читаем и парсим файл\n                        with open(file_path, 'r', encoding='utf-8') as f:\n                            content = json.load(f)\n                        \n                        # Проверяем наличие секции identity\n                        if isinstance(content, dict) and \"identity\" in content:\n                            identity = content.get(\"identity\", {})\n                            meta = content.get(\"meta\", {})\n                            content_data = content.get(\"content\", {})\n                            navigation = content.get(\"navigation\", None)\n                            \n                            # Получаем информацию о файле\n                            file_size_kb = file_path.stat().st_size / 1024\n                            mod_time = datetime.datetime.fromtimestamp(file_path.stat().st_mtime)\n                            \n                            # Создаём объект HoneycombInfo\n                            honeycomb = HoneycombInfo(\n                                path=str(file_path.relative_to(self.base_path)),\n                                identity=identity,\n                                meta=meta,\n                                content=content_data,\n                                navigation=navigation,\n                                size_kb=file_size_kb,\n                                last_modified=mod_time\n                            )\n                            \n                            # Добавляем в кэш и результат\n                            self._honeycombs_cache.append(honeycomb)\n                            honeycombs.append({\n                                \"path\": honeycomb.path,\n                                \"identity\": honeycomb.identity,\n                                \"meta\": honeycomb.meta,\n                                \"type\": honeycomb.type.value,\n                                \"status\": honeycomb.status.value,\n                                \"layer\": honeycomb.layer,\n                                \"resonance\": honeycomb.resonance,\n                                \"version\": honeycomb.version,\n                                \"size_kb\": honeycomb.size_kb,\n                                \"last_modified\": honeycomb.last_modified.isoformat() if honeycomb.last_modified else None,\n                                \"module_id\": honeycomb.module_id,\n                                \"name\": honeycomb.name\n                            })\n                            \n                            self.scan_stats[\"honeycombs_found\"] += 1\n                            \n                    except json.JSONDecodeError:\n                        # Невалидный JSON\n                        self.scan_stats[\"errors\"] += 1\n                    except Exception as e:\n                        # Другие ошибки\n                        self.scan_stats[\"errors\"] += 1\n                        print(f\"Ошибка при обработке файла {file_path}: {e}\")\n        \n        # Завершаем сканирование\n        self.scan_stats[\"scan_end_time\"] = datetime.datetime.now()\n        self.scan_stats[\"scan_duration\"] = (\n            self.scan_stats[\"scan_end_time\"] - self.scan_stats[\"scan_start_time\"]\n        ).total_seconds()\n        \n        return honeycombs\n    \n    def categorize_honeycombs(self) -> Dict[str, Dict[str, Any]]:\n        \"\"\"\n        Категоризация найденных сот по типам\n        \n        Returns:\n            Словарь категорий с информацией о сотах\n        \"\"\"\n        if not self._honeycombs_cache:\n            return {}\n        \n        categories = {}\n        \n        for honeycomb in self._honeycombs_cache:\n            honeycomb_type = honeycomb.type.value\n            \n            if honeycomb_type not in categories:\n                categories[honeycomb_type] = {\n                    \"count\": 0,\n                    \"total_size_kb\": 0.0,\n                    \"honeycombs\": []\n                }\n            \n            categories[honeycomb_type][\"count\"] += 1\n            categories[honeycomb_type][\"total_size_kb\"] += honeycomb.size_kb\n            categories[honeycomb_type][\"honeycombs\"].append({\n                \"path\": honeycomb.path,\n                \"name\": honeycomb.name,\n                \"module_id\": honeycomb.module_id,\n                \"status\": honeycomb.status.value,\n                \"layer\": honeycomb.layer,\n                \"resonance\": honeycomb.resonance\n            })\n        \n        return categories\n    \n    def calculate_statistics(self) -> Dict[str, Any]:\n        \"\"\"\n        Расчёт статистики по найденным сотам\n        \n        Returns:\n            Словарь со статистикой\n        \"\"\"\n        if not self._honeycombs_cache:\n            return {\n                \"total_honeycombs\": 0,\n                \"active_honeycombs\": 0,\n                \"inactive_honeycombs\": 0,\n                \"status_distribution\": {},\n                \"resonance_distribution\": {},\n                \"layer_distribution\": {},\n                \"average_size_kb\": 0.0,\n                **self.scan_stats\n            }\n        \n        # Распределение по статусам\n        status_dist = {}\n        for honeycomb in self._honeycombs_cache:\n            status = honeycomb.status.value\n            status_dist[status] = status_dist.get(status, 0) + 1\n        \n        # Распределение по резонансу\n        resonance_dist = {}\n        for honeycomb in self._honeycombs_cache:\n            resonance = honeycomb.resonance\n            resonance_dist[resonance] = resonance_dist.get(resonance, 0) + 1\n        \n        # Распределение по слоям\n        layer_dist = {}\n        for honeycomb in self._honeycombs_cache:\n            layer = honeycomb.layer\n            layer_dist[layer] = layer_dist.get(layer, 0) + 1\n        \n        # Подсчёт активных/неактивных сот\n        active_count = sum(1 for h in self._honeycombs_cache if h.status == HoneycombStatus.ACTIVE)\n        inactive_count = len(self._honeycombs_cache) - active_count\n        \n        # Средний размер\n        total_size = sum(h.size_kb for h in self._honeycombs_cache)\n        average_size = total_size / len(self._honeycombs_cache) if self._honeycombs_cache else 0.0\n        \n        return {\n            \"total_honeycombs\": len(self._honeycombs_cache),\n            \"active_honeycombs\": active_count,\n            \"inactive_honeycombs\": inactive_count,\n            \"status_distribution\": status_dist,\n            \"resonance_distribution\": resonance_dist,\n            \"layer_distribution\": layer_dist,\n            \"average_size_kb\": round(average_size, 2),\n            \"total_size_kb\": round(total_size, 2),\n            **self.scan_stats\n        }\n    \n    def generate_registry(self) -> Dict[str, Any]:\n        \"\"\"\n        Генерация обновлённого реестра на основе найденных сот\n        \n        Returns:\n            Словарь с обновлённым реестром\n        \"\"\"\n        # Если соты ещё не сканированы - сканируем\n        if not self._honeycombs_cache:\n            self.scan_directory()\n        \n        # Получаем категории и статистику\n        categories = self.categorize_honeycombs()\n        statistics = self.calculate_statistics()\n        \n        # Создаём список всех сот для реестра\n        all_honeycombs = []\n        for honeycomb in self._honeycombs_cache:\n            all_honeycombs.append({\n                \"module_id\": honeycomb.module_id,\n                \"name\": honeycomb.name,\n                \"path\": honeycomb.path,\n                \"type\": honeycomb.type.value,\n                \"status\": honeycomb.status.value,\n                \"layer\": honeycomb.layer,\n                \"resonance\": honeycomb.resonance,\n                \"version\": honeycomb.version,\n                \"size_kb\": honeycomb.size_kb,\n                \"last_modified\": honeycomb.last_modified.isoformat() if honeycomb.last_modified else None\n            })\n        \n        # Сортируем соты по типу и имени\n        all_honeycombs.sort(key=lambda x: (x[\"type\"], x[\"name\"]))\n        \n        # Определяем здоровье системы\n        health_status = \"good\"\n        issues_found = 0\n        \n        # Проверяем наличие критических сот\n        critical_honeycombs = [\n            \"honeycombs/core_map/index.json\",\n            \"honeycombs/registry/index.json\",\n            \"honeycombs/roadmaps/index.json\",\n            \"honeycombs/seeds/index.json\"\n        ]\n        \n        missing_critical = []\n        for critical_path in critical_honeycombs:\n            if not any(h[\"path\"] == critical_path for h in all_honeycombs):\n                missing_critical.append(critical_path)\n                issues_found += 1\n        \n        if missing_critical:\n            health_status = \"warning\"\n        \n        # Проверяем статусы сот\n        inactive_honeycombs = [h for h in all_honeycombs if h[\"status\"] != \"active\"]\n        if len(inactive_honeycombs) > len(all_honeycombs) * 0.3:  # Если больше 30% неактивных\n            health_status = \"warning\"\n            issues_found += 1\n        \n        # Создаём обновлённый реестр\n        registry_update = {\n            \"identity\": {\n                \"module_id\": \"REGISTRY-INDEX\",\n                \"name\": \"Главный индекс реестра сот\",\n                \"version\": \"v1.0.0\",\n                \"created\": \"2026-03-05\",\n                \"updated\": datetime.datetime.now().strftime(\"%Y-%m-%d\"),\n                \"layer\": 2,\n                \"type\": \"registry_index\",\n                \"description\": \"Централизованный реестр всех сот в системе с автоматическим обновлением\",\n                \"st