   }\n        }\n        \n        return registry_update\n    \n    def save_registry(self, output_path: str = \"honeycombs/registry/index.json\") -> bool:\n        \"\"\"\n        Сохранение обновлённого реестра в файл\n        \n        Args:\n            output_path: Путь для сохранения реестра\n            \n        Returns:\n            True если успешно, False если ошибка\n        \"\"\"\n        try:\n            registry_data = self.generate_registry()\n            \n            # Создаём директорию если её нет\n            output_dir = Path(output_path).parent\n            output_dir.mkdir(parents=True, exist_ok=True)\n            \n            # Сохраняем файл\n            with open(output_path, 'w', encoding='utf-8') as f:\n                json.dump(registry_data, f, ensure_ascii=False, indent=2)\n            \n            print(f\"✅ Реестр сохранён в {output_path}\")\n            print(f\"   Всего сот: {registry_data['content']['registry']['total_honeycombs']}\")\n            print(f\"   Активных: {registry_data['content']['registry']['active_honeycombs']}\")\n            print(f\"   Здоровье системы: {registry_data['content']['health']['overall_health']}\")\n            \n            return True\n            \n        except Exception as e:\n            print(f\"❌ Ошибка при сохранении реестра: {e}\")\n            return False\n    \n    def print_summary(self):\n        \"\"\"Вывод сводки сканирования\"\"\"\n        if not self._honeycombs_cache:\n            print(\"⚠️ Соты не найдены. Запустите scan_directory() сначала.\")\n            return\n        \n        stats = self.calculate_statistics()\n        categories = self.categorize_honeycombs()\n        \n        print(\"📊 Сводка сканирования сот:\")\n        print(f\"   Всего файлов проверено: {stats['total_files_scanned']}\")\n        print(f\"   JSON файлов найдено: {stats['json_files_found']}\")\n        print(f\"   Сот обнаружено: {stats['honeycombs_found']}\")\n        print(f\"   Ошибок при